sealed class RedisCache<T>
{
    private readonly IDatabase _db;
    public RedisCache(IDatabase db) => _db = db;

    public void Set(string key, T value, TimeSpan ttl) =>
        _db.StringSet(key, JsonSerializer.Serialize(value), ttl);
}

static TValue GetOrAdd<TKey, TValue>(
    Dictionary<TKey, TValue> map,
    TKey key,
    Func<TKey, TValue> factory)
    where TKey : notnull
{
    if (map.TryGetValue(key, out TValue? existing))
        return existing;
    TValue created = factory(key);
    map[key] = created;
    return created;
}

